#!/bin/sh
# Build the busycoq halting proof of 1RB0LC_1RC1RA_1LD0RE_1LA1LD_0RA0RF_0LD--- (bbchallenge 155900).
# usage: sh build.sh /path/to/busycoq
#   (a checkout of the BB6 branch of https://github.com/ccz181078/busycoq, tested at 33209bc: the proof uses its
#   Individual62.v)
# Needs Coq 8.18 or later (tested with 8.18.0). About 33 minutes, nearly all of it the final evaluation run_ok.
# H155900.v is generated by tools/coq/t4engine/proof/build.sh from busycoq PR 93's file; this script only compiles it.
set -e
BC=${1:?give the path of a busycoq checkout (BB6 branch)}
HERE=$(cd "$(dirname "$0")" && pwd)
V="$BC/verify"
cp "$HERE"/H155900.v "$V"/
cd "$V"
[ -f Makefile.coq ] || make Makefile.coq > /dev/null
make -f Makefile.coq Individual62.vo > /dev/null 2>&1
t0=$(date +%s)
coqc -Q . BusyCoq H155900.v
printf 'From BusyCoq Require Import H155900.\nPrint Assumptions halt.\n' > PA155900.v
coqc -Q . BusyCoq PA155900.v
echo "compiled in $(( $(date +%s) - t0 )) s"
